'use client';

import React from 'react';

interface LoadingSkeletonProps {
  count?: number;
}

/**
 * Modernized lightweight Train Search Loading Skeleton (Phase 1).
 * Mirrors DirectTrainCard geometry using a single GPU-accelerated CSS shimmer
 * overlay per card. Avoids multiple simultaneous animate-pulse nodes to prevent
 * CPU churn on mobile and low-end devices. Respects prefers-reduced-motion.
 */
export function LoadingSkeleton({ count = 3 }: LoadingSkeletonProps) {
  const items = Array.from({ length: Math.max(1, count) }, (_, idx) => idx);

  return (
    <div
      role="status"
      aria-label="Searching for available trains"
      aria-busy="true"
      className="space-y-5 w-full py-1"
    >
      <span className="sr-only">Searching for available trains…</span>
      {items.map((i) => (
        <div
          key={i}
          className="bg-card/85 rounded-3xl p-6 sm:p-7 border border-strong relative overflow-hidden shadow-sm select-none"
        >
          {/* Single GPU-accelerated shimmer sweep layer */}
          <div
            className="absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/8 dark:via-white/[0.04] to-transparent animate-shimmer motion-reduce:animate-none pointer-events-none z-10"
            aria-hidden="true"
          />

          {/* Card Content Top Row: Train Number, Name & Badges */}
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-4">
            <div className="space-y-2">
              <div className="flex items-center gap-2">
                {/* Train number pill */}
                <div className="h-5 w-24 bg-input/70 rounded-md" />
                {/* Confidence pill */}
                <div className="h-5 w-28 bg-input/40 rounded-lg hidden sm:block" />
              </div>
              {/* Train Name */}
              <div className="h-6 w-48 sm:w-64 bg-input/80 rounded-xl" />
            </div>

            {/* Risk & Route schedule pills */}
            <div className="flex items-center gap-2 self-start sm:self-auto">
              <div className="h-6 w-20 bg-input/50 rounded-full" />
              <div className="h-6 w-32 bg-input/40 rounded-xl hidden md:block" />
            </div>
          </div>

          {/* Route Breadcrumb Bar */}
          <div className="h-7 w-56 sm:w-72 bg-input/30 rounded-xl mb-5 border border-subtle/50" />

          {/* Departure - Timeline - Arrival Grid */}
          <div className="flex items-center justify-between gap-4 py-3 px-1 mb-5">
            {/* Departure */}
            <div className="space-y-1.5 min-w-[72px]">
              <div className="h-8 w-20 bg-input/90 rounded-lg" />
              <div className="h-3 w-12 bg-input/50 rounded" />
            </div>

            {/* Journey Timeline */}
            <div className="flex-1 px-3 sm:px-6 relative flex items-center justify-center">
              <div className="h-[2px] w-full bg-input/60 rounded-full" />
              <div className="absolute h-6 px-3 bg-card border border-subtle rounded-full flex items-center justify-center">
                <div className="h-2.5 w-14 bg-input/70 rounded" />
              </div>
            </div>

            {/* Arrival */}
            <div className="space-y-1.5 min-w-[72px] text-right flex flex-col items-end">
              <div className="h-8 w-20 bg-input/90 rounded-lg" />
              <div className="h-3 w-12 bg-input/50 rounded" />
            </div>
          </div>

          {/* Class selector pills */}
          <div className="pt-4 border-t border-strong/40">
            <div className="h-3 w-28 bg-input/40 rounded mb-3" />
            <div className="flex flex-wrap gap-2 mb-4">
              <div className="h-10 w-16 sm:w-20 bg-input/70 rounded-xl" />
              <div className="h-10 w-16 sm:w-20 bg-input/50 rounded-xl" />
              <div className="h-10 w-16 sm:w-20 bg-input/50 rounded-xl" />
              <div className="h-10 w-16 sm:w-20 bg-input/50 rounded-xl hidden sm:block" />
            </div>

            {/* 4-Day Date Cards Grid (2x2 on mobile, 4-col on desktop) */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
              {[0, 1, 2, 3].map((d) => (
                <div
                  key={d}
                  className="h-20 bg-input/20 border border-subtle/40 rounded-xl p-2.5 flex flex-col justify-between"
                >
                  <div className="h-3 w-14 bg-input/60 rounded" />
                  <div className="space-y-1">
                    <div className="h-3.5 w-16 bg-input/50 rounded" />
                    <div className="h-2.5 w-10 bg-input/40 rounded" />
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Subordinate Same-Train Rescue CTA bar */}
          <div className="mt-4 h-10 w-full bg-input/40 rounded-xl border border-subtle/40" />
        </div>
      ))}
    </div>
  );
}
