'use client';

import React, { useEffect, useState } from 'react';
import { GitFork, Sparkles, Clock, ShieldCheck, TrainFront } from 'lucide-react';
import { formatStationWithCode } from '../../utils/stationNames';

interface SplitJourneyLoaderProps {
  originStation?: string;
  destStation?: string;
  showHeader?: boolean;
  compact?: boolean;
}

const STATUS_STEPS = [
  "Scanning Grand Trunk & high-priority junction combinations...",
  "Evaluating seat availability across connecting segments...",
  "Filtering optimal layover windows (1.5h - 3h safe buffers)...",
  "Ranking feasible routes by confirmation probability..."
];

export function SplitJourneyLoader({ 
  originStation, 
  destStation,
  showHeader = true,
  compact = false 
}: SplitJourneyLoaderProps) {
  const [stepIdx, setStepIdx] = useState(0);
  const [progress, setProgress] = useState(15);

  useEffect(() => {
    const stepTimer = setInterval(() => {
      setStepIdx((prev) => (prev + 1) % STATUS_STEPS.length);
    }, 1800);

    const progressTimer = setInterval(() => {
      setProgress((prev) => {
        if (prev < 40) return prev + Math.floor(Math.random() * 4 + 3);
        if (prev < 75) return prev + Math.floor(Math.random() * 3 + 2);
        if (prev < 90) return prev + Math.floor(Math.random() * 2 + 1);
        if (prev < 96) return prev + 1;
        return prev;
      });
    }, 220);

    return () => {
      clearInterval(stepTimer);
      clearInterval(progressTimer);
    };
  }, []);

  return (
    <div className={`w-full select-none ${compact ? 'space-y-2' : 'space-y-3'}`}>
      {showHeader && (
        <div className="flex items-center gap-2.5 px-1">
          <div className="w-7 h-7 rounded-full bg-blue-500/15 border border-blue-500/30 flex items-center justify-center text-blue-500 dark:text-blue-400 shrink-0 shadow-xs">
            <TrainFront className="w-3.5 h-3.5" />
          </div>
          <span className="text-xs font-black uppercase tracking-wider text-blue-600 dark:text-blue-400 font-mono">
            AI SPLIT JOURNEYS
          </span>
          <div className="flex-1 h-px bg-gradient-to-r from-blue-500/40 via-blue-500/20 to-transparent ml-2" />
        </div>
      )}

      <div
        role="status"
        aria-label="Finding best split routes"
        aria-busy="true"
        className={`w-full bg-card border border-strong ${compact ? 'rounded-2xl p-4 sm:p-5' : 'rounded-3xl p-6 sm:p-8'} shadow-sm relative overflow-hidden text-center select-none`}
      >
        {/* Background ambient gradient glow */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-72 h-36 bg-blue-500/10 dark:bg-blue-500/15 rounded-full blur-3xl pointer-events-none" />

        {/* Floating Telemetry Pill (Percentage Progress) */}
        <div className="inline-flex items-center gap-2 px-3.5 py-1 bg-input/80 dark:bg-surface/80 border border-subtle rounded-full text-xs font-semibold text-muted mb-2.5 shadow-xs backdrop-blur-sm">
          <Sparkles className="w-3.5 h-3.5 text-blue-500 animate-pulse shrink-0" />
          <span className="font-mono font-bold text-blue-600 dark:text-blue-400">{progress}%</span>
          <span className="text-muted/40">•</span>
          <span>AI Split Routing Engine</span>
        </div>

        {/* Modern Slim Progress Bar matching Image 1 cyan-to-purple gradient */}
        <div className="w-48 max-w-full mx-auto h-1.5 bg-input rounded-full overflow-hidden border border-subtle/50 mb-6">
          <div
            className="h-full bg-gradient-to-r from-cyan-400 via-blue-500 to-indigo-500 rounded-full transition-all duration-300 ease-out shadow-xs"
            style={{ width: `${progress}%` }}
          />
        </div>

      {/* Custom SVG Rail Transit Connection Animation (Reel 2 inspired cubic-bezier loop) */}
      <div className="relative max-w-sm mx-auto mb-6 px-4">
        <svg
          viewBox="0 0 340 70"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          className="w-full h-auto overflow-visible"
        >
          <defs>
            {/* Gradient for rail line */}
            <linearGradient id="railGrad" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#3B82F6" stopOpacity="0.3" />
              <stop offset="50%" stopColor="#6366F1" stopOpacity="0.9" />
              <stop offset="100%" stopColor="#3B82F6" stopOpacity="0.3" />
            </linearGradient>

            {/* Glowing pulse marker */}
            <radialGradient id="pulseGlow" cx="50%" cy="50%" r="50%">
              <stop offset="0%" stopColor="#60A5FA" stopOpacity="1" />
              <stop offset="70%" stopColor="#3B82F6" stopOpacity="0.6" />
              <stop offset="100%" stopColor="#3B82F6" stopOpacity="0" />
            </radialGradient>
          </defs>

          {/* Background guide track */}
          <path
            d="M 30 35 L 170 35 L 310 35"
            stroke="currentColor"
            strokeWidth="3"
            strokeLinecap="round"
            className="text-subtle/70"
          />

          {/* Railroad tie dashes */}
          <path
            d="M 30 35 L 170 35 L 310 35"
            stroke="currentColor"
            strokeWidth="8"
            strokeDasharray="1.5 12"
            className="text-subtle/40"
          />

          {/* Animated active path line */}
          <path
            d="M 30 35 L 170 35 L 310 35"
            stroke="url(#railGrad)"
            strokeWidth="4"
            strokeLinecap="round"
            className="animated-rail-stroke"
          />

          {/* Station Node A: Origin */}
          <g transform="translate(30, 35)">
            <circle r="12" className="fill-card stroke-blue-500" strokeWidth="2.5" />
            <circle r="4.5" className="fill-blue-500" />
          </g>

          {/* Station Node B: Intermediate Junction Hub */}
          <g transform="translate(170, 35)">
            <circle r="16" className="fill-blue-500/15 animate-ping opacity-40" />
            <circle r="13" className="fill-card stroke-indigo-500" strokeWidth="3" />
            <circle r="5.5" className="fill-indigo-600" />
          </g>

          {/* Station Node C: Destination */}
          <g transform="translate(310, 35)">
            <circle r="12" className="fill-card stroke-blue-500" strokeWidth="2.5" />
            <circle r="4.5" className="fill-blue-500" />
          </g>

          {/* Moving Train / Packet Glow Indicator */}
          <circle
            r="7"
            fill="url(#pulseGlow)"
            className="train-travel-pulse"
          />
          <circle
            r="3"
            fill="#FFFFFF"
            className="train-travel-dot"
          />
        </svg>

        {/* Station Labels below track */}
        <div className="flex justify-between items-center text-[11px] font-semibold text-muted tracking-wide mt-1.5 px-2 gap-2">
          <span className="truncate max-w-[130px] sm:max-w-[160px]" title={formatStationWithCode(originStation) || 'Origin'}>
            {formatStationWithCode(originStation) || 'Origin'}
          </span>
          <span className="px-2 py-0.5 bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 rounded-md font-bold text-[10px] shrink-0">
            Intermediate Hub
          </span>
          <span className="truncate max-w-[130px] sm:max-w-[160px]" title={formatStationWithCode(destStation) || 'Destination'}>
            {formatStationWithCode(destStation) || 'Destination'}
          </span>
        </div>
      </div>

      {/* Dynamic Headline */}
      <h3 className="text-base sm:text-lg font-bold text-main mb-2">
        Finding Best Split Rail Combinations
      </h3>

      {/* Rotating Status Step */}
      <div className="h-6 flex items-center justify-center">
        <p
          key={stepIdx}
          className="text-xs sm:text-sm text-muted max-w-md mx-auto transition-opacity duration-300 animate-fade-in"
        >
          {STATUS_STEPS[stepIdx]}
        </p>
      </div>

      {/* Quick reassurance pills */}
      <div className="flex flex-wrap justify-center items-center gap-4 mt-6 pt-5 border-t border-subtle/60 text-[11px] text-muted">
        <div className="flex items-center gap-1.5">
          <ShieldCheck className="w-3.5 h-3.5 text-emerald-500" />
          <span>No Confirmed Train? Split Unlocks Seats</span>
        </div>
        <div className="flex items-center gap-1.5">
          <Clock className="w-3.5 h-3.5 text-blue-500" />
          <span>Minimum 1h 30m Layover Safe Buffer</span>
        </div>
        <div className="flex items-center gap-1.5">
          <GitFork className="w-3.5 h-3.5 text-indigo-500" />
          <span>Dual Leg PNR Guarantee</span>
        </div>
      </div>

      {/* Inline styles for GPU-accelerated bezier keyframe animation */}
      <style jsx>{`
        @keyframes railWorm {
          0% {
            stroke-dasharray: 40 280;
            stroke-dashoffset: 0;
          }
          50% {
            stroke-dasharray: 120 200;
            stroke-dashoffset: -100;
          }
          100% {
            stroke-dasharray: 40 280;
            stroke-dashoffset: -280;
          }
        }

        @keyframes trainMove {
          0% {
            cx: 30px;
            cy: 35px;
            opacity: 0.3;
          }
          15% {
            opacity: 1;
          }
          85% {
            opacity: 1;
          }
          100% {
            cx: 310px;
            cy: 35px;
            opacity: 0.3;
          }
        }

        .animated-rail-stroke {
          animation: railWorm 2.2s cubic-bezier(0.42, 0.17, 0.75, 0.63) infinite;
        }

        .train-travel-pulse,
        .train-travel-dot {
          animation: trainMove 2.2s cubic-bezier(0.42, 0.17, 0.75, 0.63) infinite;
        }
      `}</style>
      </div>
    </div>
  );
}
