// ── Same Train Rescue helpers ──────────────────────────────────────────────────

function resolveLegAvailability(leg: any): string {
  if (!leg?.availability) return '';
  if (typeof leg.availability === 'string') return leg.availability;
  return leg.availability?.status || leg.availability?.availabilityText || '';
}

function rankRescueOptions(options: any[]): any[] {
  if (!options || options.length === 0) return [];
  
  const getAvailabilityScore = (status?: string): number => {
    if (!status) return 0;
    const s = status.toUpperCase();
    if (s.includes('AVAILABLE') || s.includes('AVL') || s.includes('CNF')) {
      const match = s.match(/\d+/);
      const avlNum = match ? parseInt(match[0], 10) : 50;
      return 1000 + avlNum;
    }
    if (s.includes('RAC')) {
      const match = s.match(/\d+/);
      const racNum = match ? parseInt(match[0], 10) : 10;
      return 500 - racNum;
    }
    if (s.includes('WL')) {
      const match = s.match(/\d+/);
      const wlNum = match ? parseInt(match[0], 10) : 100;
      return 100 - wlNum;
    }
    return 0;
  };

  const getOptionScore = (opt: any) => {
    const leg1Avail = resolveLegAvailability(opt.leg1);
    const leg2Avail = resolveLegAvailability(opt.leg2);
    const availScore = getAvailabilityScore(leg1Avail) + getAvailabilityScore(leg2Avail);

    const coach1 = opt.leg1?.availability?.coach || opt.leg1?.coach;
    const coach2 = opt.leg2?.availability?.coach || opt.leg2?.coach;
    const isSameCoach = coach1 && coach2 && coach1 === coach2;
    const continuityScore = isSameCoach ? 200 : 0;

    const baseScore = opt.score || opt.success_percent || 50;

    let simplicityScore = 50;
    if (coach1 && coach2) {
      const c1Num = parseInt(coach1.replace(/\D/g, ''), 10);
      const c2Num = parseInt(coach2.replace(/\D/g, ''), 10);
      if (!isNaN(c1Num) && !isNaN(c2Num)) {
        simplicityScore = Math.max(0, 100 - Math.abs(c1Num - c2Num) * 10);
      }
    }

    return availScore + continuityScore + baseScore + simplicityScore;
  };

  const scored = options.map(opt => {
    const leg1Avail = resolveLegAvailability(opt.leg1).toUpperCase();
    const leg2Avail = resolveLegAvailability(opt.leg2).toUpperCase();
    const hasCnf = leg1Avail.includes('CNF') || leg1Avail.includes('AVAILABLE') || leg1Avail.includes('AVL') ||
                   leg2Avail.includes('CNF') || leg2Avail.includes('AVAILABLE') || leg2Avail.includes('AVL');
    const hasRac = leg1Avail.includes('RAC') || leg2Avail.includes('RAC');
    const isDoubleWl = leg1Avail.includes('WL') && leg2Avail.includes('WL');
    return {
      opt,
      score: getOptionScore(opt),
      hasCnf,
      hasRac,
      isDoubleWl,
    };
  });
  scored.sort((a, b) => b.score - a.score);
  return scored.map((s, idx) => ({
    ...s.opt,
    isBestOption: idx === 0 && (s.hasCnf || s.hasRac),
    isDoubleWl: s.isDoubleWl,
  }));
}

function RescueStatusBadge({ status }: { status?: string }) {
  if (!status) return <Badge variant="outline">PENDING</Badge>;
  if (status.toLowerCase().includes('unlock')) return null;
  const parsed = parseRailwayAvailability(status);
  return (
    <span
      className={clsx(
        "inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[10px] font-black border tabular-nums shadow-xs",
        parsed.badgeClass
      )}
      title={parsed.explanation}
    >
      <span>{parsed.iconSymbol}</span>
      <span>{parsed.statusBadge}</span>
    </span>
  );
}

