function InlineSplitRouteCard({
  split,
  date,
  index,
  handleCheckAvailability,
  availabilityMap,
  loadingTrain,
  selectedQuota = 'GN',
  defaultClass = 'SL',
}: {
  split: any;
  date: string;
  index: number;
  handleCheckAvailability?: (params: any) => void;
  availabilityMap?: any;
  loadingTrain?: Record<string, boolean>;
  selectedQuota?: string;
  defaultClass?: string;
}) {
  const leg1 = split.legs?.[0] || split.leg1 || {};
  const leg2 = split.legs?.[1] || split.leg2 || {};
  const hubCode = (split.hub || split.via || leg1.toCode || leg1.to || leg1.destination || '').toUpperCase();
  const hubDetails = getStationDetails(hubCode);
  const bufferMins = Number(split.layover_minutes || split.buffer_minutes || split.buffer || split.wait_time || 0);

  const l1TrainNo = String(leg1.train_number || leg1.trainNo || leg1.train_num || '').padStart(5, '0');
  const l1TrainName = leg1.train_name || leg1.trainName || 'Connecting Express';
  const l1From = (leg1.origin || leg1.fromCode || leg1.from || '').toUpperCase();
  const l1To = (leg1.destination || leg1.toCode || leg1.to || hubCode).toUpperCase();
  const l1Dep = leg1.departure || leg1.depTime || '--:--';
  const l1Arr = leg1.arrival || leg1.arrTime || '--:--';
  const l1Date = leg1.travelDate || leg1.journeyDate || date;

  const l2TrainNo = String(leg2.train_number || leg2.trainNo || leg2.train_num || '').padStart(5, '0');
  const l2TrainName = leg2.train_name || leg2.trainName || 'Connecting Express';
  const l2From = (leg2.origin || leg2.fromCode || leg2.from || hubCode).toUpperCase();
  const l2To = (leg2.destination || leg2.toCode || leg2.to || '').toUpperCase();
  const l2Dep = leg2.departure || leg2.depTime || '--:--';
  const l2Arr = leg2.arrival || leg2.arrTime || '--:--';
  const l2Date = leg2.travelDate || leg2.journeyDate || date;

  const l1FromDetails = getStationDetails(l1From, leg1.fromName || leg1.origin_name);
  const l1ToDetails = getStationDetails(l1To, leg1.toName || leg1.destination_name || hubDetails.name);
  const l2FromDetails = getStationDetails(l2From, leg2.fromName || leg2.origin_name || hubDetails.name);
  const l2ToDetails = getStationDetails(l2To, leg2.toName || leg2.destination_name);

  const totalDuration = split.total_duration || split.duration || '';

  const bufferLabel = bufferMins >= 120
    ? `${bufferMins}m (Safe layover)`
    : bufferMins >= 60
    ? `${bufferMins}m (Moderate layover)`
    : `${bufferMins}m (Tight layover)`;

  const bufferBadgeClass = bufferMins >= 120
    ? 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-400 border-emerald-500/30'
    : bufferMins >= 60
    ? 'bg-amber-500/10 text-amber-700 dark:text-amber-400 border-amber-500/30'
    : 'bg-rose-500/10 text-rose-700 dark:text-rose-400 border-rose-500/30';

  // Supported classes
  const l1Classes = useMemo(() => getTrainSupportedClasses({ trainNumber: l1TrainNo, trainName: l1TrainName, classes: leg1.classes }), [l1TrainNo, l1TrainName, leg1.classes]);
  const l2Classes = useMemo(() => getTrainSupportedClasses({ trainNumber: l2TrainNo, trainName: l2TrainName, classes: leg2.classes }), [l2TrainNo, l2TrainName, leg2.classes]);

  const [l1SelectedClass, setL1SelectedClass] = useState<string>(() => getDefaultActiveClass(l1Classes, defaultClass));
  const [l2SelectedClass, setL2SelectedClass] = useState<string>(() => getDefaultActiveClass(l2Classes, defaultClass));

  // Local state fallbacks if parent availabilityMap is not passed
  const [localAvailMap, setLocalAvailMap] = useState<Record<string, any>>({});
  const [localLoading, setLocalLoading] = useState<Record<string, boolean>>({});

  const targetQuota = (selectedQuota || 'GN').toUpperCase().trim();

  const storeLocalAvailabilityResponse = (key: string, data: any) => {
    const isUnknown = data?.success === false && data.reason === 'AVAILABILITY_UNKNOWN';
    const value = isUnknown
      ? {
          error: true,
          reason: 'AVAILABILITY_UNKNOWN',
          type: 'unknown',
          message: 'Could not confirm availability. Please retry.',
        }
      : data?.availability
        ? data.availability
        : { error: true, message: data?.message || 'Check failed' };
    setLocalAvailMap(prev => ({ ...prev, [key]: value }));
  };

  // Keys for leg 1 and leg 2
  const l1Key = `${l1TrainNo}_${l1From}_${l1To}_${l1SelectedClass}_${l1Date}_${targetQuota}`;
  const l1LegacyKey = `${l1TrainNo}_${l1From}_${l1To}_${l1SelectedClass}_${l1Date}`;
  const l2Key = `${l2TrainNo}_${l2From}_${l2To}_${l2SelectedClass}_${l2Date}_${targetQuota}`;
  const l2LegacyKey = `${l2TrainNo}_${l2From}_${l2To}_${l2SelectedClass}_${l2Date}`;

  const isL1Loading = Boolean(loadingTrain?.[l1Key] || (targetQuota === 'GN' && loadingTrain?.[l1LegacyKey]) || localLoading[l1Key]);
  const isL2Loading = Boolean(loadingTrain?.[l2Key] || (targetQuota === 'GN' && loadingTrain?.[l2LegacyKey]) || localLoading[l2Key]);

  const l1AvailData = availabilityMap?.[l1Key] ?? (targetQuota === 'GN' ? availabilityMap?.[l1LegacyKey] : undefined) ?? localAvailMap[l1Key];
  const l2AvailData = availabilityMap?.[l2Key] ?? (targetQuota === 'GN' ? availabilityMap?.[l2LegacyKey] : undefined) ?? localAvailMap[l2Key];

  // Resolve status for Leg 1
  let l1Status = '';
  let l1Fare: any = null;
  let l1IsVerified = false;
  let l1IsError = false;
  let l1ErrorMsg = '';

  if (l1AvailData && !('error' in l1AvailData)) {
    const val = l1AvailData[l1SelectedClass] || Object.values(l1AvailData).find((v: any) => v && typeof v === 'object' && v.status);
    if (val && val.status) {
      l1Status = String(val.status);
      l1IsVerified = true;
      l1Fare = typeof val.fare === 'object' && val.fare !== null
        ? (val.fare.totalFare ?? val.fare.total_fare ?? val.fare.total ?? null)
        : val.fare;
    }
  } else if (l1AvailData && 'error' in l1AvailData) {
    l1IsError = true;
    l1ErrorMsg = l1AvailData.message || 'Availability check failed';
  } else {
    l1Status = resolveLegAvailability(leg1) || leg1.status || leg1.current_status || split.leg1_status || '';
  }

  // Resolve status for Leg 2
  let l2Status = '';
  let l2Fare: any = null;
  let l2IsVerified = false;
  let l2IsError = false;
  let l2ErrorMsg = '';

  if (l2AvailData && !('error' in l2AvailData)) {
    const val = l2AvailData[l2SelectedClass] || Object.values(l2AvailData).find((v: any) => v && typeof v === 'object' && v.status);
    if (val && val.status) {
      l2Status = String(val.status);
      l2IsVerified = true;
      l2Fare = typeof val.fare === 'object' && val.fare !== null
        ? (val.fare.totalFare ?? val.fare.total_fare ?? val.fare.total ?? null)
        : val.fare;
    }
  } else if (l2AvailData && 'error' in l2AvailData) {
    l2IsError = true;
    l2ErrorMsg = l2AvailData.message || 'Availability check failed';
  } else {
    l2Status = resolveLegAvailability(leg2) || leg2.status || leg2.current_status || split.leg2_status || '';
  }

  const l1Parsed = parseRailwayAvailability(l1Status);
  const l2Parsed = parseRailwayAvailability(l2Status);

  const handleCheckLeg1 = async () => {
    if (handleCheckAvailability) {
      handleCheckAvailability({
        trainNo: l1TrainNo,
        from: l1From,
        to: l1To,
        classType: l1SelectedClass,
        travelDate: l1Date,
        quota: targetQuota,
      });
    } else {
      setLocalLoading(prev => ({ ...prev, [l1Key]: true }));
      try {
        const res = await axios.get(`${API_BASE}/trains/availability`, {
          params: { trainNo: l1TrainNo, from: l1From, to: l1To, date: l1Date, classType: l1SelectedClass, quota: targetQuota },
        });
        storeLocalAvailabilityResponse(l1Key, res.data);
      } catch (err: any) {
        setLocalAvailMap(prev => ({ ...prev, [l1Key]: { error: true, message: 'Check failed' } }));
      } finally {
        setLocalLoading(prev => ({ ...prev, [l1Key]: false }));
      }
    }
  };

  const handleCheckLeg2 = async () => {
    if (handleCheckAvailability) {
      handleCheckAvailability({
        trainNo: l2TrainNo,
        from: l2From,
        to: l2To,
        classType: l2SelectedClass,
        travelDate: l2Date,
        quota: targetQuota,
      });
    } else {
      setLocalLoading(prev => ({ ...prev, [l2Key]: true }));
      try {
        const res = await axios.get(`${API_BASE}/trains/availability`, {
          params: { trainNo: l2TrainNo, from: l2From, to: l2To, date: l2Date, classType: l2SelectedClass, quota: targetQuota },
        });
        storeLocalAvailabilityResponse(l2Key, res.data);
      } catch (err: any) {
        setLocalAvailMap(prev => ({ ...prev, [l2Key]: { error: true, message: 'Check failed' } }));
      } finally {
        setLocalLoading(prev => ({ ...prev, [l2Key]: false }));
      }
    }
  };

  return (
    <div className="bg-card dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 rounded-2xl p-4 space-y-3 overflow-hidden text-left shadow-xs">
      {/* Top Header: Route Index, Via Hub, Buffer Badge */}
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <div className="flex items-center gap-1.5 flex-wrap">
          <span className="text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full bg-primary/10 text-primary border border-primary/20">
            Route #{index + 1}
          </span>
          <span className="text-xs font-bold text-slate-800 dark:text-slate-200">
            Via <span className="font-black text-primary">{hubDetails.name || hubCode}</span> ({hubCode})
          </span>
        </div>
        <div className="flex items-center gap-1.5">
          {totalDuration && (
            <span className="text-[10px] font-bold text-slate-600 dark:text-slate-400 tabular-nums">
              {totalDuration}
            </span>
          )}
          <span className={clsx("text-[10px] font-black px-2 py-0.5 rounded-full border tabular-nums", bufferBadgeClass)}>
            {bufferLabel}
          </span>
        </div>
      </div>

      {/* Two-Leg Progression with Leg-Wise Availability Inspection */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 bg-slate-50 dark:bg-slate-900/60 p-3 rounded-xl border border-slate-200 dark:border-slate-800 text-xs">
        {/* Leg 1 */}
        <div className="space-y-2 border-b sm:border-b-0 sm:border-r border-slate-200 dark:border-slate-800 pb-3 sm:pb-0 sm:pr-3 flex flex-col justify-between">
          <div>
            <div className="flex items-center justify-between gap-1 flex-wrap mb-1">
              <span className="text-[10px] font-black uppercase tracking-wider text-primary">
                Leg 1: #{l1TrainNo}
              </span>
              <span className="text-[10px] font-mono font-bold text-slate-700 dark:text-slate-300 tabular-nums">
                {l1Dep} → {l1Arr}
              </span>
            </div>
            <p className="font-extrabold text-slate-900 dark:text-white truncate text-[11px] mb-0.5">
              {l1TrainName}
            </p>
            <div className="flex items-center gap-1 text-[11px] font-semibold text-slate-700 dark:text-slate-300 mb-1 flex-wrap">
              <span className="font-bold text-slate-900 dark:text-white">{l1FromDetails.name} <span className="font-mono text-slate-500">({l1From})</span></span>
              <ArrowRight className="w-3 h-3 text-slate-400 shrink-0" />
              <span className="font-bold text-primary">{l1ToDetails.name} <span className="font-mono text-slate-500">({l1To})</span></span>
            </div>
            <span className="text-[10px] font-medium text-slate-500 dark:text-slate-400 tabular-nums block mb-2">
              📅 {l1Date}
            </span>

            {/* Availability Pill & Seat Summary */}
            <div className="p-2.5 rounded-xl border bg-white dark:bg-slate-800/90 border-slate-200 dark:border-slate-700 space-y-1.5 shadow-xs">
              <div className="flex items-center justify-between gap-1 flex-wrap">
                <span className={clsx("inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[10px] font-black border tabular-nums shadow-xs", l1Parsed.badgeClass)}>
                  {l1Parsed.iconSymbol} {l1Parsed.statusBadge}
                </span>
                <span className={clsx(
                  "text-[9px] font-black uppercase tracking-wider",
                  l1IsVerified ? "text-emerald-700 dark:text-emerald-400" : "text-slate-500"
                )}>
                  {l1IsVerified ? "● Live Verified" : "○ Estimated"}
                </span>
              </div>
              <div className="flex items-baseline justify-between gap-1 pt-1 border-t border-slate-200/60 dark:border-slate-700 text-xs">
                <span className="font-extrabold text-slate-800 dark:text-slate-200 text-[11px]">
                  {l1Parsed.seatSummary}
                </span>
                {l1Fare && (
                  <span className="font-mono font-black text-slate-900 dark:text-white shrink-0 text-[11px] tabular-nums">
                    ₹{l1Fare}
                  </span>
                )}
              </div>
              {l1IsError && (
                <div className="text-[10px] text-rose-500 font-bold bg-rose-500/10 p-1.5 rounded border border-rose-500/20">
                  ⚠️ Check Failed: {l1ErrorMsg}
                </div>
              )}
            </div>
          </div>

          {/* Leg 1 Class Selector & Check Availability Button */}
          <div className="pt-2 border-t border-slate-200/80 dark:border-slate-800 flex items-center justify-between gap-2 flex-wrap">
            <div className="flex items-center gap-1">
              <span className="text-[10px] font-black uppercase tracking-wider text-slate-500">Class</span>
              <select
                value={l1SelectedClass}
                onChange={(e) => setL1SelectedClass(e.target.value)}
                aria-label={`Select class for Alternative Route ${index + 1} Leg 1`}
                className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-slate-100 text-[10px] font-bold rounded-lg px-1.5 py-1 outline-none cursor-pointer min-h-[30px]"
              >
                {l1Classes.map((cls: string) => (
                  <option key={cls} value={cls}>Class {cls}</option>
                ))}
              </select>
            </div>

            <button
              type="button"
              id={`check-avail-leg1-${index}-${l1TrainNo}`}
              onClick={handleCheckLeg1}
              disabled={isL1Loading}
              className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold text-primary hover:text-white bg-primary/10 hover:bg-primary border border-primary/25 transition-all cursor-pointer shadow-xs min-h-[30px] disabled:opacity-50"
            >
              {isL1Loading ? (
                <>
                  <Loader2 className="w-3 h-3 animate-spin text-primary" />
                  <span>Checking...</span>
                </>
              ) : l1IsError ? (
                <>
                  <RefreshCw className="w-3 h-3" />
                  <span>Retry Check</span>
                </>
              ) : (
                <>
                  <RefreshCw className="w-3 h-3" />
                  <span>{l1IsVerified ? 'Recheck Availability' : 'Check Availability'}</span>
                </>
              )}
            </button>
          </div>
        </div>

        {/* Leg 2 */}
        <div className="space-y-2 sm:pl-3 flex flex-col justify-between">
          <div>
            <div className="flex items-center justify-between gap-1 flex-wrap mb-1">
              <span className="text-[10px] font-black uppercase tracking-wider text-primary">
                Leg 2: #{l2TrainNo}
              </span>
              <span className="text-[10px] font-mono font-bold text-slate-700 dark:text-slate-300 tabular-nums">
                {l2Dep} → {l2Arr}
              </span>
            </div>
            <p className="font-extrabold text-slate-900 dark:text-white truncate text-[11px] mb-0.5">
              {l2TrainName}
            </p>
            <div className="flex items-center gap-1 text-[11px] font-semibold text-slate-700 dark:text-slate-300 mb-1 flex-wrap">
              <span className="font-bold text-primary">{l2FromDetails.name} <span className="font-mono text-slate-500">({l2From})</span></span>
              <ArrowRight className="w-3 h-3 text-slate-400 shrink-0" />
              <span className="font-bold text-slate-900 dark:text-white">{l2ToDetails.name} <span className="font-mono text-slate-500">({l2To})</span></span>
            </div>
            <span className="text-[10px] font-medium text-slate-500 dark:text-slate-400 tabular-nums block mb-2">
              📅 {l2Date}
            </span>

            {/* Availability Pill & Seat Summary */}
            <div className="p-2.5 rounded-xl border bg-white dark:bg-slate-800/90 border-slate-200 dark:border-slate-700 space-y-1.5 shadow-xs">
              <div className="flex items-center justify-between gap-1 flex-wrap">
                <span className={clsx("inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[10px] font-black border tabular-nums shadow-xs", l2Parsed.badgeClass)}>
                  {l2Parsed.iconSymbol} {l2Parsed.statusBadge}
                </span>
                <span className={clsx(
                  "text-[9px] font-black uppercase tracking-wider",
                  l2IsVerified ? "text-emerald-700 dark:text-emerald-400" : "text-slate-500"
                )}>
                  {l2IsVerified ? "● Live Verified" : "○ Estimated"}
                </span>
              </div>
              <div className="flex items-baseline justify-between gap-1 pt-1 border-t border-slate-200/60 dark:border-slate-700 text-xs">
                <span className="font-extrabold text-slate-800 dark:text-slate-200 text-[11px]">
                  {l2Parsed.seatSummary}
                </span>
                {l2Fare && (
                  <span className="font-mono font-black text-slate-900 dark:text-white shrink-0 text-[11px] tabular-nums">
                    ₹{l2Fare}
                  </span>
                )}
              </div>
              {l2IsError && (
                <div className="text-[10px] text-rose-500 font-bold bg-rose-500/10 p-1.5 rounded border border-rose-500/20">
                  ⚠️ Check Failed: {l2ErrorMsg}
                </div>
              )}
            </div>
          </div>

          {/* Leg 2 Class Selector & Check Availability Button */}
          <div className="pt-2 border-t border-slate-200/80 dark:border-slate-800 flex items-center justify-between gap-2 flex-wrap">
            <div className="flex items-center gap-1">
              <span className="text-[10px] font-black uppercase tracking-wider text-slate-500">Class</span>
              <select
                value={l2SelectedClass}
                onChange={(e) => setL2SelectedClass(e.target.value)}
                aria-label={`Select class for Alternative Route ${index + 1} Leg 2`}
                className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-slate-100 text-[10px] font-bold rounded-lg px-1.5 py-1 outline-none cursor-pointer min-h-[30px]"
              >
                {l2Classes.map((cls: string) => (
                  <option key={cls} value={cls}>Class {cls}</option>
                ))}
              </select>
            </div>

            <button
              type="button"
              id={`check-avail-leg2-${index}-${l2TrainNo}`}
              onClick={handleCheckLeg2}
              disabled={isL2Loading}
              className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold text-primary hover:text-white bg-primary/10 hover:bg-primary border border-primary/25 transition-all cursor-pointer shadow-xs min-h-[30px] disabled:opacity-50"
            >
              {isL2Loading ? (
                <>
                  <Loader2 className="w-3 h-3 animate-spin text-primary" />
                  <span>Checking...</span>
                </>
              ) : l2IsError ? (
                <>
                  <RefreshCw className="w-3 h-3" />
                  <span>Retry Check</span>
                </>
              ) : (
                <>
                  <RefreshCw className="w-3 h-3" />
                  <span>{l2IsVerified ? 'Recheck Availability' : 'Check Availability'}</span>
                </>
              )}
            </button>
          </div>
        </div>
      </div>

      {/* Booking Guidance / External Link */}
      <div className="flex items-center justify-between gap-2 pt-1 flex-wrap">
        <span className="text-[10px] text-slate-500">
          Book Leg 1 then Leg 2 via IRCTC
        </span>
        <a
          href="https://www.irctc.co.in/nget/train-search"
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-primary hover:bg-primary-hover text-white text-xs font-bold shadow-xs transition-colors cursor-pointer"
        >
          <span>Book on IRCTC</span>
          <ExternalLink className="w-3 h-3" />
        </a>
      </div>
    </div>
  );
}

export const DirectTrainCard = ({
  train,
  source,
  destination,
  date,
  selectedClass,
  selectedClassByLeg,
  selectedQuota = 'GN',
  availabilityMap,
  loadingTrain,
  handleCheckAvailability,
  getTrainInfo,
  getCode,
  getRiskColor,
  isSponsored = false,
  isSelected = false,
  onSelectTrain,
  onTriggerSplitSearch,
  splitLoading = false,
}: {
  train: any;
  source: string;
  destination: string;
  date: string;
  selectedClass: string;
  selectedClassByLeg: any;
  selectedQuota?: string;
  availabilityMap: any;
  loadingTrain: Record<string, boolean>;
  handleCheckAvailability: (params: any) => void;
  getTrainInfo: (train: any) => any;
  getCode: (val: any) => string;
  getRiskColor: (risk: string) => string;
  isSponsored?: boolean;
  isSelected?: boolean;
  onSelectTrain?: () => void;
  onTriggerSplitSearch?: () => void;
  splitLoading?: boolean;
}) => {
  const info    = getTrainInfo(train);
  const trainNo = train.trainNo || train.number || train.train_number;
  const fromStn = getCode(train._fromCode || train.fromStationCode || train.from_station_code || train.fromCode || train.from || train.source || source);
  const toStn   = getCode(train._toCode   || train.toStationCode   || train.to_station_code   || train.toCode   || train.to   || train.destination || destination);
  const directFromDetails = getStationDetails(fromStn, train.fromStationName || train.fromName || (train.source !== fromStn ? train.source : undefined));
  const directToDetails   = getStationDetails(toStn, train.toStationName || train.toName || (train.destination !== toStn ? train.destination : undefined));

  // ── Rescue state ────────────────────────────────────────────────────────────
  const [rescueLoading, setRescueLoading]   = useState(false);
  const [rescueOptions, setRescueOptions]   = useState<any[] | null>(null);
  const [rescueExpanded, setRescueExpanded] = useState(false);
  const [rescueError, setRescueError]       = useState<string | null>(null);
  // ── Inline Alternative Split Routes state ──────────────────────────────────
  const [cardSplitLoading, setCardSplitLoading]     = useState(false);
  const [cardSplitResults, setCardSplitResults]     = useState<any[] | null>(null);
  const [cardSplitExpanded, setCardSplitExpanded]   = useState(false);
  const [cardSplitError, setCardSplitError]         = useState<string | null>(null);
  const [showAllCardSplits, setShowAllCardSplits]   = useState(false);
  const [cardSplitExhausted, setCardSplitExhausted] = useState(false);
  const supportedClasses = useMemo(() => getTrainSupportedClasses(train || { trainNo }), [train, trainNo]);
  const initialClass = useMemo(() => {
    const requested = selectedClassByLeg[`${String(trainNo).padStart(5, '0')}_${fromStn}_${toStn}`] || selectedClass;
    return getDefaultActiveClass(supportedClasses, requested);
  }, [supportedClasses, selectedClassByLeg, trainNo, fromStn, toStn, selectedClass]);

  const [rescueClass, setRescueClass]       = useState<string>(initialClass);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [scheduleModalTab, setScheduleModalTab]   = useState<'schedule' | 'coaches'>('schedule');
  const [showPaywallModal, setShowPaywallModal]   = useState(false);
  const [showLoginModal, setShowLoginModal]       = useState(false);
  const [loginContextMessage, setLoginContextMessage] = useState('Please sign in to use AI Split Journey & Seat Rescue');
  const [paywallAction, setPaywallAction]         = useState<'rescue' | 'split'>('rescue');
  const [rescueFunnelTracked, setRescueFunnelTracked] = useState(false);
  const [splitFunnelTracked, setSplitFunnelTracked]   = useState(false);

  const [isPaidUser, setIsPaidUser] = useState(false);
  useEffect(() => {
    setIsPaidUser(isPaidOrAdminUser());
    const handleStorage = () => setIsPaidUser(isPaidOrAdminUser());
    window.addEventListener('storage', handleStorage);
    return () => window.removeEventListener('storage', handleStorage);
  }, []);

  // Reset contextual inline states when unselected or when train/class changes
  useEffect(() => {
    if (!isSelected) {
      setRescueOptions(null);
      setRescueExpanded(false);
      setRescueError(null);
      setCardSplitResults(null);
      setCardSplitExpanded(false);
      setCardSplitError(null);
      setCardSplitLoading(false);
      setShowAllCardSplits(false);
      setCardSplitExhausted(false);
    }
  }, [isSelected]);

  const currentClass = rescueClass || selectedClass;
  const effectiveQuota = (selectedQuota || 'GN').toUpperCase().trim();
  const currentKey = `${trainNo}_${fromStn}_${toStn}_${currentClass}_${train.travelDate || date}_${effectiveQuota}`;
  const currentAvail = availabilityMap?.[currentKey] ?? (effectiveQuota === 'GN' ? availabilityMap?.[`${trainNo}_${fromStn}_${toStn}_${currentClass}_${train.travelDate || date}`] : undefined);
  const availStatus = typeof currentAvail === 'object' && currentAvail && !('error' in currentAvail)
    ? (currentAvail[currentClass]?.status || currentAvail.status || '')
    : '';

  const rawFare = currentAvail && typeof currentAvail === 'object' && !('error' in currentAvail)
    ? (currentAvail[currentClass]?.fare ?? currentAvail.fare)
    : train.fare;
  const resolvedFare = rawFare
    ? (typeof rawFare === 'object' ? (rawFare.totalFare || rawFare.total_fare || rawFare.total) : rawFare)
    : null;
  const journeyDate = train.travelDate || date;

  const isWaitlisted = Boolean(
    availStatus && (
      availStatus.toUpperCase().includes('WL') ||
      availStatus.toUpperCase().includes('RAC') ||
      availStatus.toUpperCase().includes('REGRET')
    )
  );

  const { language, setLanguage } = useLanguage();
  const [isVoicePlaying, setIsVoicePlaying] = useState(false);
  const [cardVoiceLang, setCardVoiceLang] = useState<'hi' | 'en'>(() => {
    if (typeof window !== 'undefined') {
      const saved = voiceService.getLanguage();
      if (saved === 'en') return 'en';
    }
    return 'hi';
  });

  useEffect(() => {
    const handleSync = (e: any) => {
      const l = e.detail?.lang;
      if (l === 'hi' || l === 'en') {
        setCardVoiceLang(l);
      }
    };
    window.addEventListener('trayago:language-change', handleSync);
    return () => window.removeEventListener('trayago:language-change', handleSync);
  }, []);

  useEffect(() => {
    return () => {
      if (isVoicePlaying) {
        voiceService.stop();
      }
    };
  }, [isVoicePlaying]);

  const handleSelectCardVoiceLang = (newLang: 'hi' | 'en') => {
    setCardVoiceLang(newLang);
    voiceService.setLanguage(newLang);
    try {
      setLanguage(newLang);
    } catch {}

    const wasPlaying = isVoicePlaying;
    voiceService.stop();
    setIsVoicePlaying(false);

    if (wasPlaying) {
      setTimeout(() => {
        playSearchVoice(newLang);
      }, 250);
    }
  };

  const playSearchVoice = (langToUse: 'hi' | 'en') => {
    const tName = train.train_name || train.name || train.trainName || train.train_base?.train_name || '';
    setIsVoicePlaying(true);

    voiceService.speakSearchWaitlistAdvice(
      tName,
      String(trainNo),
      currentClass,
      availStatus,
      source || fromStn,
      destination || toStn,
      langToUse,
      'female',
      () => {
        setIsVoicePlaying(false);
      }
    );
  };

  const handlePlayVoiceAdvice = (e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    if (isVoicePlaying) {
      voiceService.stop();
      setIsVoicePlaying(false);
      return;
    }
    playSearchVoice(cardVoiceLang);
  };

  const hasConfirmedRescue = useMemo(() => {
    if (!rescueOptions || rescueOptions.length === 0) return false;
    return rescueOptions.some(opt => {
      const l1 = resolveLegAvailability(opt.leg1).toUpperCase();
      const l2 = resolveLegAvailability(opt.leg2).toUpperCase();
      return (l1.includes('AVL') || l1.includes('CNF')) && (l2.includes('AVL') || l2.includes('CNF'));
    });
  }, [rescueOptions]);

  const rescueScanned = rescueOptions !== null;
  const rescueFailedOrWl = rescueScanned && (!hasConfirmedRescue || rescueOptions.length === 0);

  useEffect(() => {
    if (isWaitlisted && !rescueScanned && !rescueFunnelTracked) {
      trackEvent('rescue_cta_shown', undefined, { trainNo, from: fromStn, to: toStn, classCode: currentClass, status: availStatus });
      setRescueFunnelTracked(true);
    }
  }, [isWaitlisted, rescueScanned, rescueFunnelTracked, trainNo, fromStn, toStn, currentClass, availStatus]);

  useEffect(() => {
    if (isWaitlisted && rescueFailedOrWl && !splitFunnelTracked) {
      trackEvent('split_cta_shown', undefined, { trainNo, from: fromStn, to: toStn, classCode: currentClass });
      setSplitFunnelTracked(true);
    }
  }, [isWaitlisted, rescueFailedOrWl, splitFunnelTracked, trainNo, fromStn, toStn, currentClass]);

  const handleFunnelAction = async (actionType: 'rescue' | 'split') => {
    setPaywallAction(actionType);
    if (!isPaidUser) {
      const userStr = typeof window !== 'undefined' ? localStorage.getItem('user') : null;
      const isGuest = !userStr || userStr === 'null' || userStr === 'undefined';
      if (isGuest) {
        setLoginContextMessage('Please sign in to use AI Split Journey & Seat Rescue');
        setShowLoginModal(true);
        return;
      }
      const ent = await checkRescueEntitlement(actionType);
      if (!ent.allowed) {
        trackEvent('paywall_shown', undefined, { actionType, source: 'waitlist_funnel', trainNo });
        setShowPaywallModal(true);
        return;
      }

      if (ent.source === 'free_credit') {
        await consumeRescueFreeCredit(actionType);
      }
    }

    if (actionType === 'rescue') {
      trackEvent('rescue_cta_clicked', undefined, { trainNo, from: fromStn, to: toStn, classCode: currentClass });
      handleRescueScan();
    } else {
      trackEvent('split_cta_clicked', undefined, { trainNo, from: fromStn, to: toStn, classCode: currentClass });
      const splitElem = document.getElementById('split-journey-section') || document.getElementById('split-results');
      if (splitElem) {
        splitElem.scrollIntoView({ behavior: 'smooth' });
      } else {
        window.scrollTo({ top: document.body.scrollHeight / 2, behavior: 'smooth' });
      }
    }
  };

  const handleUnlockRescueCard = async () => {
    const userStr = typeof window !== 'undefined' ? localStorage.getItem('user') : null;
    const isGuest = !userStr || userStr === 'null' || userStr === 'undefined';
    if (isGuest) {
      setLoginContextMessage('Please sign in to use AI Split Journey & Seat Rescue');
      setShowLoginModal(true);
      return;
    }
    setPaywallAction('rescue');
    const ent = await checkRescueEntitlement('rescue');
    if (ent.allowed) {
      if (ent.source === 'free_credit') {
        await consumeRescueFreeCredit('rescue');
      }
      // Force rescan
      setRescueOptions(null);
      setTimeout(() => {
        handleRescueScan();
      }, 50);
    } else {
      trackEvent('paywall_shown', undefined, { actionType: 'rescue_locked_card', source: 'waitlist_funnel', trainNo });
      setShowPaywallModal(true);
    }
  };

  const handleRescueScan = async () => {
    if (rescueOptions !== null) {
      // Toggle panel if already scanned
      setRescueExpanded(e => !e);
      return;
    }
    const userStr = typeof window !== 'undefined' ? localStorage.getItem('user') : null;
    const isGuest = !userStr || userStr === 'null' || userStr === 'undefined';
    if (isGuest) {
      setLoginContextMessage('Please sign in to use AI Split Journey & Seat Rescue');
      setShowLoginModal(true);
      return;
    }
    setRescueLoading(true);
    setRescueError(null);
    try {
      analytics.waitlistRescueTriggered(fromStn, toStn);
      const { buildAuthHeaders } = await import('@/lib/authHeaders');
      const { ensureAccessToken } = await import('@/lib/sessionBootstrap');
      await ensureAccessToken();
      const res = await axios.post(`${API_BASE}/api/trains/same-train-rescue`, {
        trainNo,
        source:      fromStn,
        destination: toStn,
        journeyDate: train.travelDate || date,
        classCode:   rescueClass,
      }, { headers: buildAuthHeaders() });
      const data = res.data;
      setRescueOptions(rankRescueOptions(data.rescueOptions || []));
      setRescueExpanded(true);
      analytics.sameTrainSegmentFound(fromStn, toStn, data.rescueOptions?.length || 0);
    } catch (e: any) {
      const errStatus = e?.response?.status;
      const errCode = e?.response?.data?.code || e?.response?.data?.error;
      if (errStatus === 401 || errCode === 'REQUIRE_LOGIN' || errCode === 'UNAUTHORIZED') {
        setRescueError(null);
        setLoginContextMessage('Please sign in to use AI Split Journey & Seat Rescue');
        setShowLoginModal(true);
        return;
      }
      setRescueError('Rescue scan failed. Please try again.');
    } finally {
      setRescueLoading(false);
    }
  };

  const handleCardSplitSearch = async (forceExcludeVia?: any) => {
    const excludeList: string[] = Array.isArray(forceExcludeVia) ? forceExcludeVia : [];
    if (cardSplitResults !== null && excludeList.length === 0) {
      setCardSplitExpanded(e => !e);
      return;
    }
    const userStr = typeof window !== 'undefined' ? localStorage.getItem('user') : null;
    const isGuest = !userStr || userStr === 'null' || userStr === 'undefined';
    if (isGuest) {
      setLoginContextMessage('Please sign in to use AI Split Journey & Seat Rescue');
      setShowLoginModal(true);
      return;
    }
    setCardSplitLoading(true);
    setCardSplitError(null);
    try {
      analytics.waitlistRescueTriggered(fromStn, toStn);
      const { buildAuthHeaders } = await import('@/lib/authHeaders');
      const { ensureAccessToken } = await import('@/lib/sessionBootstrap');
      await ensureAccessToken();
      const params: any = {
        source: fromStn,
        destination: toStn,
        date: train.travelDate || date,
        includeSplit: 'true',
      };
      if (excludeList.length > 0) {
        params.excludeVia = excludeList.join(',');
      }
      const res = await axios.get(`${API_BASE}/api/trains/search-advanced`, {
        params,
        headers: buildAuthHeaders(),
        timeout: 80000,
      });
      const splitData = res.data?.splitRoutes || res.data?.splits || res.data?.split || [];
      const splits = Array.isArray(splitData) ? splitData.filter(Boolean) : [];
      if (excludeList.length > 0 && cardSplitResults) {
        const existingKeys = new Set(cardSplitResults.map(s => `${s.hub || s.via}_${s.legs?.[0]?.train_number || s.legs?.[0]?.trainNo}_${s.legs?.[1]?.train_number || s.legs?.[1]?.trainNo}`));
        const newSplits = splits.filter((s: any) => !existingKeys.has(`${s.hub || s.via}_${s.legs?.[0]?.train_number || s.legs?.[0]?.trainNo}_${s.legs?.[1]?.train_number || s.legs?.[1]?.trainNo}`));
        if (newSplits.length === 0) {
          setCardSplitExhausted(true);
        } else {
          setCardSplitResults(prev => [...(prev || []), ...newSplits]);
        }
      } else {
        setCardSplitResults(splits);
      }
      setCardSplitExpanded(true);
    } catch (err: any) {
      const errStatus = err?.response?.status;
      const errCode = err?.response?.data?.code || err?.response?.data?.error;
      if (errStatus === 401 || errCode === 'REQUIRE_LOGIN' || errCode === 'UNAUTHORIZED') {
        setCardSplitError(null);
        setLoginContextMessage('Please sign in to use AI Split Journey & Seat Rescue');
        setShowLoginModal(true);
        return;
      }
      setCardSplitError(err?.response?.data?.message || 'Failed to search split routes. Please try again.');
    } finally {
      setCardSplitLoading(false);
    }
  };

  const handleGenerateMoreCardSplits = () => {
    if (!cardSplitResults || cardSplitResults.length === 0) return;
    const shownVias = Array.from(new Set(cardSplitResults.map((s: any) => s.hub || s.via).filter(Boolean)));
    handleCardSplitSearch(shownVias);
  };

  const isCancelled = train.isCancelled === true;
  const isRecommended = !isCancelled && ((train.confirmation_probability !== undefined && train.confirmation_probability >= 80) || train.isFastest === true || train.isBestOption === true);

  return (
    <React.Fragment>
      <Card
        id={`direct-train-card-${trainNo || "unknown"}`}
        hoverable
        onClick={() => {
          if (!isSelected && onSelectTrain) {
            onSelectTrain();
          }
        }}
        className={clsx(
          "p-4 sm:p-6 rounded-2xl sm:rounded-3xl border backdrop-blur-md shadow-sm transition-all duration-300 relative overflow-hidden",
          isSelected
            ? "border-blue-500/80 bg-card ring-2 ring-blue-500/30 shadow-lg shadow-blue-500/10"
            : isCancelled
            ? "border-rose-500/50 bg-rose-500/5 opacity-75 grayscale pointer-events-none"
            : isRecommended
            ? "border-blue-500/40 bg-card/95 shadow-md hover:shadow-elevated hover:border-primary/40 cursor-pointer"
            : "border-slate-200/90 dark:border-slate-800 bg-card hover:shadow-elevated hover:border-primary/30 cursor-pointer"
        )}
      >
        {isRecommended && (
          <BorderBeam size={280} duration={12} colorFrom="#3b82f6" colorTo="#10b981" />
        )}
        <div className="flex flex-col gap-3 relative z-10">
          {/* ── Header: Badges & Train Identity ── */}
          <div className="flex flex-col gap-2">
            <div className="flex items-center justify-between gap-2 flex-wrap">
              {/* Train Number Pill & Recommended Tag */}
              <div className="flex items-center gap-2 flex-wrap">
                <div className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-primary/10 border border-primary/20 text-primary font-mono font-bold text-xs tracking-wider shadow-xs">
                  <Train className="w-3.5 h-3.5 shrink-0" />
                  <span>{info.number !== "Train number unavailable" ? `Train ${info.number}` : "Train number unavailable"}</span>
                </div>
                {isSelected && (
                  <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-md text-[10px] font-black uppercase tracking-wider bg-blue-600 text-white shadow-xs">
                    <CheckCircle className="w-3 h-3" /> Selected Train
                  </span>
                )}
                {isRecommended && (
                  <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-md text-[10px] font-black uppercase tracking-wider bg-blue-500/10 text-blue-600 dark:text-blue-400 border border-blue-500/25 shadow-xs">
                    <Sparkles className="w-3 h-3 text-blue-500" /> Recommended
                  </span>
                )}
              </div>

              {/* Status Badges Cluster */}
              <div className="flex items-center gap-2 flex-wrap">
                {train.confirmation_probability !== undefined && (
                  <div
                    className={clsx(
                      "inline-flex items-center gap-1.5 px-2.5 py-1 text-xs font-bold rounded-lg border shadow-xs",
                      train.confirmation_probability >= 85
                        ? "bg-emerald-500/10 text-emerald-600 border-emerald-500/30 dark:text-emerald-400"
                        : train.confirmation_probability >= 70
                        ? "bg-blue-500/10 text-blue-600 border-blue-500/30 dark:text-blue-400"
                        : train.confirmation_probability >= 40
                        ? "bg-amber-500/10 text-amber-600 border-amber-500/30 dark:text-amber-400"
                        : train.confirmation_probability >= 15
                        ? "bg-orange-500/10 text-orange-600 border-orange-500/30 dark:text-orange-400"
                        : "bg-rose-500/10 text-rose-600 border-rose-500/30 dark:text-rose-400"
                    )}
                  >
                    <Sparkles className="w-3.5 h-3.5 shrink-0" />
                    <span>{train.confidence_badge} ({train.confirmation_probability}%)</span>
                  </div>
                )}
                {train.risk_level && (
                  <Badge
                    variant={
                      train.risk_level.toLowerCase() === 'high'
                        ? 'destructive'
                        : train.risk_level.toLowerCase() === 'moderate'
                        ? 'warning'
                        : 'success'
                    }
                  >
                    {train.risk_level} RISK
                  </Badge>
                )}
                {isCancelled && (
                  <Badge variant="destructive" className="uppercase tracking-widest font-black animate-pulse">
                    🚨 Cancelled Today
                  </Badge>
                )}
              </div>
            </div>

            {/* Train Name */}
            <h3
              className="text-base sm:text-xl font-black text-main tracking-tight line-clamp-1 break-words"
              title={info.name}
            >
              {info.name}
            </h3>
          </div>

          {/* ── Route & Timetable Action Bar ── */}
          <div className="flex flex-wrap items-center justify-between gap-2.5 my-1 pointer-events-auto">
            <div className="inline-flex items-center gap-1.5 text-[11px] font-mono font-bold text-secondary bg-input/40 border border-subtle px-2.5 py-1.5 rounded-xl flex-wrap">
              <span className="text-main font-black" title={directFromDetails.name}>
                {directFromDetails.name !== directFromDetails.code ? `${directFromDetails.name} (${directFromDetails.code})` : directFromDetails.code}
              </span>
              <ArrowRight size={11} className="text-primary shrink-0" />
              {Array.isArray(train.intermediateStations) && train.intermediateStations.length > 0 ? (
                <>
                  {train.intermediateStations.slice(0, 3).map((stn: string, idx: number) => {
                    const stnDetails = getStationDetails(stn);
                    return (
                      <React.Fragment key={idx}>
                        <span className="text-secondary/80" title={stnDetails.name}>{stnDetails.code || stn}</span>
                        <ArrowRight size={10} className="text-muted/60 shrink-0" />
                      </React.Fragment>
                    );
                  })}
                  {train.intermediateStations.length > 3 && (
                    <span className="text-muted text-[10px]">...</span>
                  )}
                </>
              ) : Array.isArray(train.route) && train.route.length > 2 ? (
                <>
                  {train.route.slice(1, 4).map((r: any, idx: number) => {
                    const rawStn = r.code || r.stationCode || r;
                    const stnDetails = getStationDetails(rawStn);
                    return (
                      <React.Fragment key={idx}>
                        <span className="text-secondary/80" title={stnDetails.name}>{stnDetails.code || rawStn}</span>
                        <ArrowRight size={10} className="text-muted/60 shrink-0" />
                      </React.Fragment>
                    );
                  })}
                  {train.route.length > 5 && (
                    <span className="text-muted text-[10px]">...</span>
                  )}
                </>
              ) : null}
              <span className="text-main font-black" title={directToDetails.name}>
                {directToDetails.name !== directToDetails.code ? `${directToDetails.name} (${directToDetails.code})` : directToDetails.code}
              </span>
            </div>

            <div className="flex items-center justify-end gap-1.5 sm:gap-2 flex-wrap ml-auto">
              {/* Train Running Days Schedule Strip (M T W T F S S) */}
              <TrainRunningDays
                runningDays={train.runningDays || train.running_days || train.scheduleDays || train.days}
                searchDate={date}
              />
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setScheduleModalTab('schedule');
                  setShowScheduleModal(true);
                }}
                className="inline-flex items-center gap-1.5 text-[11px] font-bold text-blue-500 dark:text-blue-400 bg-blue-500/10 border border-blue-500/20 px-3 py-1.5 rounded-xl hover:bg-blue-500/20 transition-all active:scale-95 cursor-pointer shadow-xs min-h-[36px]"
                title="View Full Route & Stops"
                aria-label="View Full Route & Timetable"
              >
                <CalendarClock size={13} className="shrink-0" />
                <span>Timetable</span>
              </button>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setScheduleModalTab('coaches');
                  setShowScheduleModal(true);
                }}
                className="inline-flex items-center gap-1.5 text-[11px] font-bold text-amber-600 dark:text-amber-400 bg-amber-500/10 border border-amber-500/25 hover:border-amber-500/40 px-3 py-1.5 rounded-xl hover:bg-amber-500/20 transition-all active:scale-95 cursor-pointer shadow-xs min-h-[36px]"
                title="View Train Coach Position & Composition"
                aria-label="View Train Coach Position"
              >
                <Train size={13} className="shrink-0 text-amber-500" />
                <span>Coach Position</span>
              </button>
              <LiveTelemetryBadge />
            </div>
          </div>

          {/* ── Responsive Departure / Arrival Timeline (ALWAYS VISIBLE on Mobile, Tablet & Desktop) ── */}
          <div className="my-2 p-3.5 sm:p-4 rounded-2xl bg-input/25 border border-subtle">
            <div className="grid grid-cols-[1fr_auto_1fr] items-center gap-2 sm:gap-4">
              {/* Departure */}
              <div className="flex flex-col min-w-0">
                <span className="text-2xl sm:text-3xl font-black text-main tracking-tight font-mono tabular-nums">
                  {train.departure}
                </span>
                <div className="flex items-center gap-1 mt-0.5 truncate" title={`${directFromDetails.name} (${directFromDetails.code})`}>
                  <span className="text-[10px] sm:text-xs font-black text-secondary uppercase tracking-wider truncate">
                    {directFromDetails.name}
                  </span>
                  {directFromDetails.code && (
                    <span className="text-[9px] font-mono font-bold text-muted">({directFromDetails.code})</span>
                  )}
                </div>
              </div>

              {/* Center Duration & Rail Connector (NEVER HIDDEN ON MOBILE) */}
              <div className="flex flex-col items-center justify-center px-1 sm:px-3 min-w-[95px] sm:min-w-[140px]">
                <div className="inline-flex items-center gap-1 px-2.5 py-0.5 sm:px-3 sm:py-1 rounded-full bg-primary/10 border border-primary/20 text-primary text-[10px] sm:text-xs font-bold whitespace-nowrap shadow-xs tabular-nums">
                  <Clock className="w-3 h-3 shrink-0" />
                  <span className="tabular-nums">{train.total_journey_time || train.duration}</span>
                </div>
                {/* Visual Connector Track */}
                <div className="w-full flex items-center justify-center gap-1 mt-1.5">
                  <div className="h-[2px] w-full bg-gradient-to-r from-transparent via-primary/30 to-primary/60 rounded-full" />
                  <div className="w-2 h-2 rounded-full border-2 border-primary bg-card shrink-0" />
                  <div className="h-[2px] w-full bg-gradient-to-r from-primary/60 via-primary/30 to-transparent rounded-full" />
                </div>
                <span className="text-[9px] font-bold text-muted tracking-widest uppercase mt-1">
                  Direct
                </span>
              </div>

              {/* Arrival */}
              <div className="flex flex-col items-end text-right min-w-0">
                <span className="text-2xl sm:text-3xl font-black text-main tracking-tight font-mono tabular-nums">
                  {train.arrival}
                </span>
                <div className="flex items-center justify-end gap-1 mt-0.5 truncate" title={`${directToDetails.name} (${directToDetails.code})`}>
                  <span className="text-[10px] sm:text-xs font-black text-secondary uppercase tracking-wider truncate">
                    {directToDetails.name}
                  </span>
                  {directToDetails.code && (
                    <span className="text-[9px] font-mono font-bold text-muted">({directToDetails.code})</span>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* ── Availability Panel ── */}
          <AvailabilityPanel
            trainNo={trainNo}
            fromStn={fromStn}
            toStn={toStn}
            date={train.travelDate || date}
            selectedClass={rescueClass || selectedClass}
            selectedQuota={selectedQuota || 'GN'}
            availabilityMap={availabilityMap}
            loadingTrain={loadingTrain}
            handleCheckAvailability={handleCheckAvailability}
            train={train}
            onSelectClass={(cls: string) => {
              setRescueClass(cls);
              setRescueOptions(null);
              setRescueExpanded(false);
              if (!isSelected && onSelectTrain) {
                onSelectTrain();
              }
            }}
          />

          {/* ── Unselected Train Quick Interactive Bar ── */}
          {!isSelected && (
            <div className="mt-2.5">
              {isWaitlisted ? (
                <button
                  type="button"
                  id={`btn-rescue-bar-${trainNo}`}
                  onClick={(e) => {
                    e.stopPropagation();
                    onSelectTrain?.();
                  }}
                  aria-label={`Select train ${info.number} to view rescue options`}
                  className="w-full px-3.5 py-3 rounded-2xl bg-gradient-to-r from-[#2c544a] via-[#335e53] to-[#264c42] dark:from-emerald-950/90 dark:via-teal-950/80 dark:to-emerald-950/90 hover:from-[#264c42] hover:to-[#21433a] dark:hover:from-emerald-900/80 border border-emerald-400/60 dark:border-emerald-500/70 shadow-lg shadow-emerald-950/30 ring-1 ring-emerald-400/40 text-emerald-100 flex items-center justify-between text-xs font-bold transition-all cursor-pointer active:scale-[0.99] touch-manipulation group"
                >
                  <div className="flex items-center gap-2 min-w-0 flex-wrap">
                    <Sparkles className="w-4 h-4 text-emerald-300 shrink-0 group-hover:scale-110 transition-transform" />
                    <span className="truncate font-black tracking-wide text-white dark:text-emerald-100 text-xs sm:text-[13px]">
                      Waitlisted ({availStatus || currentClass}): Seat Rescue &amp; Connecting Routes
                    </span>
                    {resolvedFare && (
                      <span className="px-2 py-0.5 rounded-lg bg-black/30 dark:bg-black/50 border border-white/10 dark:border-emerald-500/30 text-emerald-200 font-mono text-[10px] font-black shrink-0">
                        ₹{resolvedFare}
                      </span>
                    )}
                    {journeyDate && (
                      <span className="px-2 py-0.5 rounded-lg bg-black/25 dark:bg-black/40 border border-white/10 dark:border-emerald-500/20 text-emerald-300/90 font-mono text-[10px] shrink-0 hidden xs:inline-block sm:inline-block">
                        {journeyDate}
                      </span>
                    )}
                  </div>
                  <div className="flex items-center gap-2 shrink-0 ml-2">
                    <div className="flex flex-col items-end">
                      <span className="text-[11px] font-black uppercase tracking-wider text-emerald-200 dark:text-emerald-300">
                        Rescue Options
                      </span>
                      <span className="text-[9px] font-black text-emerald-300/90 tracking-tight hidden sm:inline-block">
                        सीट विकल्प देखें
                      </span>
                    </div>
                    {/* Glowing Bouncing Arrow with Ping Radar Halo */}
                    <div className="relative flex items-center justify-center">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400/60 opacity-80 motion-reduce:hidden" />
                      <div className="relative w-7 h-7 rounded-full bg-emerald-400/30 dark:bg-emerald-400/40 border border-emerald-300/80 shadow-[0_0_14px_rgba(52,211,153,0.9)] flex items-center justify-center text-white group-hover:scale-110 transition-transform">
                        <ChevronDown className="w-4 h-4 text-white group-hover:translate-y-0.5 animate-bounce motion-reduce:animate-none" />
                      </div>
                    </div>
                  </div>
                </button>
              ) : (
                <button
                  type="button"
                  id={`btn-select-train-bar-${trainNo}`}
                  onClick={(e) => {
                    e.stopPropagation();
                    onSelectTrain?.();
                  }}
                  aria-label={`Select train ${info.number} to view same-train rescue and connecting routes`}
                  className="w-full px-3.5 py-3 rounded-2xl bg-gradient-to-r from-blue-700 via-indigo-700 to-blue-800 dark:from-blue-950/95 dark:via-indigo-950/90 dark:to-blue-950/95 hover:from-blue-800 hover:to-indigo-800 dark:hover:from-blue-900/90 border border-blue-400/60 dark:border-blue-500/70 shadow-lg shadow-blue-950/25 dark:shadow-blue-950/45 ring-1 ring-blue-400/40 text-blue-100 flex items-center justify-between text-xs font-bold transition-all cursor-pointer active:scale-[0.99] touch-manipulation group"
                >
                  <div className="flex items-center gap-2 min-w-0 flex-wrap">
                    <Sparkles className="w-4 h-4 text-cyan-300 shrink-0 group-hover:scale-110 transition-transform" />
                    <span className="truncate font-black tracking-wide text-white dark:text-blue-100 text-xs sm:text-[13px]">
                      Train #{info.number}: Seat Rescue &amp; Connecting Routes
                    </span>
                    {resolvedFare && (
                      <span className="px-2 py-0.5 rounded-lg bg-black/30 dark:bg-black/50 border border-white/10 dark:border-blue-500/30 text-cyan-200 font-mono text-[10px] font-black shrink-0">
                        ₹{resolvedFare}
                      </span>
                    )}
                    <span className="px-2 py-0.5 rounded-lg bg-black/25 dark:bg-black/40 border border-white/10 dark:border-blue-500/20 text-cyan-200/90 font-mono text-[10px] shrink-0 hidden xs:inline-block sm:inline-block">
                      AI Smart Route
                    </span>
                  </div>
                  <div className="flex items-center gap-2 shrink-0 ml-2">
                    <div className="flex flex-col items-end">
                      <span className="text-[11px] font-black uppercase tracking-wider text-blue-100 dark:text-blue-200">
                        Explore Routes
                      </span>
                      <span className="text-[9px] font-black text-cyan-200/90 tracking-tight hidden sm:inline-block">
                        सीट व रूट विकल्प खोलें
                      </span>
                    </div>
                    {/* Glowing Bouncing Arrow with Ping Radar Halo */}
                    <div className="relative flex items-center justify-center">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-cyan-400/60 opacity-80 motion-reduce:hidden" />
                      <div className="relative w-7 h-7 rounded-full bg-cyan-400/30 dark:bg-cyan-400/40 border border-cyan-300/80 shadow-[0_0_14px_rgba(34,211,238,0.9)] flex items-center justify-center text-white group-hover:scale-110 transition-transform">
                        <ChevronDown className="w-4 h-4 text-white group-hover:translate-y-0.5 animate-bounce motion-reduce:animate-none" />
                      </div>
                    </div>
                  </div>
                </button>
              )}
            </div>
          )}

          {/* ── CONTEXTUAL EXPANDED PANEL (Active ONLY for the selected train) ── */}
          {isSelected && (
            <div className="mt-3.5 pt-3.5 border-t border-slate-200 dark:border-slate-700/80 space-y-3 animate-in fade-in slide-in-from-top-2 duration-300">
              
              {/* Contextual Header Bar */}
              <div className="flex items-center justify-between gap-2 p-3 rounded-xl sm:rounded-2xl bg-gradient-to-r from-blue-600/10 via-blue-500/5 to-emerald-500/10 border border-blue-500/25 shadow-xs">
                <div className="flex items-center gap-2.5 min-w-0">
                  <div className="w-8 h-8 rounded-lg bg-blue-600 text-white flex items-center justify-center font-bold text-xs shrink-0 shadow-sm">
                    <Train className="w-4 h-4" />
                  </div>
                  <div className="min-w-0">
                    <h4 className="text-xs sm:text-sm font-black text-slate-900 dark:text-white truncate">
                      Train #{info.number} {info.name}
                    </h4>
                    <p className="text-[10px] sm:text-[11px] text-slate-500 dark:text-slate-400 font-medium truncate">
                      Contextual Seat Rescue &amp; Alternative Route Options
                    </p>
                  </div>
                </div>

                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onSelectTrain?.();
                  }}
                  className="px-2.5 py-1 rounded-lg text-xs font-bold text-slate-600 dark:text-slate-300 hover:text-slate-900 dark:hover:text-white bg-white/80 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 flex items-center gap-1 cursor-pointer transition-colors shadow-xs touch-manipulation"
                  title="Close contextual panel"
                >
                  <span>Close</span>
                  <ChevronUp className="w-3.5 h-3.5" />
                </button>
              </div>

              {/* Status Advisory Strip + Voice Interaction (No Autoplay) */}
              <div className={clsx(
                "p-3 rounded-xl border flex flex-wrap items-center justify-between gap-2 transition-all",
                isWaitlisted
                  ? "bg-amber-500/10 dark:bg-amber-950/20 border-amber-500/30 shadow-[0_0_14px_rgba(245,158,11,0.12)]"
                  : "bg-slate-50 dark:bg-slate-800/60 border-slate-200 dark:border-slate-700/60"
              )}>
                <div className="flex items-center gap-2 min-w-0">
                  <span className={clsx(
                    "w-2.5 h-2.5 rounded-full shrink-0",
                    isWaitlisted ? "bg-amber-400 animate-ping" : "bg-emerald-500"
                  )} />
                  <span className="text-xs font-bold text-slate-800 dark:text-slate-200 truncate">
                    {isWaitlisted
                      ? `Waitlisted in ${currentClass} (${availStatus}) - Direct tickets unavailable`
                      : `Confirmed/Available in ${currentClass} (${availStatus})`}
                  </span>
                </div>

                {/* User-Initiated Voice Advisory CTA */}
                <div className="flex items-center gap-1.5 ml-auto shrink-0">
                  <div className="flex items-center gap-0.5 bg-white dark:bg-slate-800 p-0.5 rounded-lg border border-slate-200 dark:border-slate-700 text-[9px]">
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleSelectCardVoiceLang('hi');
                      }}
                      className={clsx(
                        "px-1.5 py-0.5 rounded-md font-bold transition-all cursor-pointer",
                        cardVoiceLang === 'hi'
                          ? "bg-blue-600 text-white font-black"
                          : "text-slate-500 hover:text-slate-900 dark:hover:text-white"
                      )}
                    >
                      हिंदी
                    </button>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleSelectCardVoiceLang('en');
                      }}
                      className={clsx(
                        "px-1.5 py-0.5 rounded-md font-bold transition-all cursor-pointer",
                        cardVoiceLang === 'en'
                          ? "bg-blue-600 text-white font-black"
                          : "text-slate-500 hover:text-slate-900 dark:hover:text-white"
                      )}
                    >
                      EN
                    </button>
                  </div>

                                    <button
                    type="button"
                    onClick={handlePlayVoiceAdvice}
                    title={isVoicePlaying ? "Stop voice advisory playback" : "Listen to dynamic AI voice advisory for this train"}
                    aria-label={isVoicePlaying ? "Stop voice advisory" : "Listen to dynamic AI voice advisory"}
                    className={clsx(
                      "relative flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-[11px] font-bold transition-all cursor-pointer border select-none",
                      "focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:outline-none",
                      "motion-reduce:transition-none motion-reduce:transform-none motion-reduce:animate-none",
                      isVoicePlaying
                        ? "bg-blue-600 text-white border-blue-400 shadow-[0_0_20px_rgba(37,99,235,0.75)] animate-pulse font-black active:scale-95 ring-2 ring-blue-300/50"
                        : "bg-blue-500/15 hover:bg-blue-500/25 text-blue-700 dark:text-blue-200 border-blue-400/60 shadow-[0_0_16px_rgba(59,130,246,0.5)] ring-2 ring-blue-400/40 hover:shadow-[0_0_22px_rgba(59,130,246,0.7)] hover:scale-105 active:scale-95 animate-[pulse_3s_ease-in-out_infinite]"
                    )}
                  >
                    {isVoicePlaying ? (
                      <>
                        <Square size={11} className="fill-current text-white shrink-0" />
                        <span className="tracking-wide font-black">{cardVoiceLang === 'hi' ? 'सलाह चल रही है (रोकें)' : 'Playing Advice (Stop)'}</span>
                        {/* Live Soundwave Equalizer Animation */}
                        <span className="flex items-end gap-0.5 h-3 ml-0.5" aria-hidden="true">
                          <span className="w-0.5 h-3 bg-white animate-[pulse_0.6s_ease-in-out_infinite]" />
                          <span className="w-0.5 h-1.5 bg-white animate-[pulse_0.4s_ease-in-out_infinite]" />
                          <span className="w-0.5 h-2.5 bg-white animate-[pulse_0.5s_ease-in-out_infinite]" />
                        </span>
                      </>
                    ) : (
                      <>
                        <div className="relative flex items-center justify-center">
                          <span className="animate-ping absolute inline-flex h-2.5 w-2.5 rounded-full bg-blue-400 opacity-75 motion-reduce:hidden" />
                          <Volume2 size={13} className="relative text-blue-600 dark:text-blue-400 shrink-0" />
                        </div>
                        <span className="font-extrabold tracking-tight">
                          {cardVoiceLang === 'hi' ? 'सलाह सुनें' : 'Listen Voice Advice'}
                        </span>
                        <span className="px-1.5 py-0.2 rounded-md bg-blue-500/20 text-[9px] font-black tracking-wider text-blue-700 dark:text-blue-300 border border-blue-500/30">
                          {cardVoiceLang === 'hi' ? 'आवाज़' : 'AUDIO'}
                        </span>
                      </>
                    )}
                  </button>
                </div>
              </div>

              {/* Contextual Dual Action Cards: Same Train Rescue (Col 1) & Alternative Split Routes (Col 2) */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3.5 items-start">
                
                {/* 1. Same Train Rescue Column */}
                <div className="p-3.5 rounded-2xl bg-card dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 hover:border-emerald-500/40 shadow-sm flex flex-col justify-between space-y-3">
                  <div>
                    <div className="flex items-center justify-between gap-1 mb-1">
                      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-black uppercase tracking-wider bg-emerald-500/10 text-emerald-700 dark:text-emerald-400 border border-emerald-500/30">
                        <Sparkles className="w-3 h-3" /> Same-Train Seat Rescue
                      </span>
                      <span className="text-[10px] font-bold text-slate-500">Zero train switch</span>
                    </div>
                    <h5 className="text-xs sm:text-sm font-black text-slate-900 dark:text-white">
                      Stay on Train #{info.number}
                    </h5>
                    <p className="text-[11px] text-slate-600 dark:text-slate-300 leading-relaxed mt-1">
                      Travel on this exact train by switching between vacant intermediate quota seats midway. 2 valid IRCTC tickets, 1 continuous journey.
                    </p>
                  </div>

                  <Button
                    id={`same-train-rescue-btn-${trainNo}`}
                    onClick={handleRescueScan}
                    disabled={rescueLoading}
                    variant="success"
                    className="w-full min-h-[40px] px-3 gap-2 bg-emerald-600 hover:bg-emerald-500 active:bg-emerald-700 text-white rounded-xl font-bold text-xs shadow-md shadow-emerald-500/20 active:scale-95 cursor-pointer touch-manipulation focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500"
                  >
                    {rescueLoading ? (
                      <Loader2 size={14} className="animate-spin shrink-0" />
                    ) : (
                      <Train size={14} className="shrink-0" />
                    )}
                    <span>
                      {rescueLoading
                        ? 'Scanning for same-train seats...'
                        : rescueOptions !== null
                        ? rescueExpanded
                          ? 'Hide Same-Train Options'
                          : `Show Same-Train Options (${rescueOptions.length})`
                        : `Check Same-Train Rescue (${rescueClass})`}
                    </span>
                    {!rescueLoading && rescueOptions !== null && (
                      rescueExpanded ? <ChevronUp size={14} /> : <ChevronDown size={14} />
                    )}
                  </Button>

                  {rescueError && (
                    <p className="text-[10px] text-rose-500 font-bold bg-rose-500/10 px-3 py-2 rounded-lg border border-rose-500/20">
                      {rescueError}
                    </p>
                  )}

                  {/* Inline Loading for Rescue */}
                  {rescueLoading && (
                    <div className="p-4 rounded-xl bg-card border border-emerald-500/20 text-center space-y-1.5 animate-in fade-in duration-200">
                      <Loader2 className="w-5 h-5 text-emerald-500 animate-spin mx-auto" />
                      <p className="text-xs font-bold text-slate-800 dark:text-slate-200">
                        Scanning intermediate quotas for Train #{info.number}...
                      </p>
                      <p className="text-[10px] text-slate-500">
                        Checking vacant station segments between {fromStn} and {toStn}
                      </p>
                    </div>
                  )}

                  {/* Inline Same-Train Rescue Options Results */}
                  {rescueExpanded && rescueOptions !== null && !rescueLoading && (
                    <div className="space-y-3 pt-2 border-t border-emerald-500/20 animate-in fade-in duration-200">
                      <div className="flex items-center justify-between px-0.5">
                        <span className="text-[11px] font-bold text-slate-700 dark:text-slate-300">
                          Available Same-Train Rescue Options ({rescueOptions.length}):
                        </span>
                      </div>
                      {rescueOptions.length === 0 ? (
                        <div className="bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl p-4 text-center">
                          <p className="text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">
                            No confirmed intermediate segment seats found on Train #{info.number}.
                          </p>
                          <p className="text-[11px] text-slate-500">
                            Consider alternative split routes connecting via major junctions.
                          </p>
                        </div>
                      ) : (
                        rescueOptions.map((opt: any, i: number) => (
                          <RescueOptionCard key={i} option={opt} index={i} onUnlock={handleUnlockRescueCard} train={train} date={date} />
                        ))
                      )}
                    </div>
                  )}
                </div>

                {/* 2. Alternative Split Routes Column */}
                <div className="p-3.5 rounded-2xl bg-card dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 hover:border-primary/40 shadow-sm flex flex-col justify-between space-y-3">
                  <div>
                    <div className="flex items-center justify-between gap-1 mb-1">
                      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-black uppercase tracking-wider bg-primary/10 text-primary border border-primary/20">
                        <ArrowRight className="w-3 h-3" /> Alternative Route Discovery
                      </span>
                      <span className="text-[10px] font-bold text-slate-500">Connecting hubs</span>
                    </div>
                    <h5 className="text-xs sm:text-sm font-black text-slate-900 dark:text-white">
                      Connecting Split Journeys
                    </h5>
                    <p className="text-[11px] text-slate-600 dark:text-slate-300 leading-relaxed mt-1">
                      Explore multi-leg routes connecting {fromStn} to {toStn} via major junctions when direct trains are fully booked.
                    </p>
                  </div>

                  <Button
                    id={`inline-split-routes-btn-${trainNo}`}
                    type="button"
                    onClick={() => handleCardSplitSearch()}
                    disabled={cardSplitLoading}
                    className="w-full min-h-[40px] px-3 gap-2 bg-blue-600 hover:bg-blue-500 active:bg-blue-700 text-white rounded-xl font-bold text-xs shadow-md shadow-blue-500/20 active:scale-95 cursor-pointer touch-manipulation"
                  >
                    {cardSplitLoading ? (
                      <Loader2 size={14} className="animate-spin shrink-0" />
                    ) : (
                      <Sparkles size={14} className="shrink-0" />
                    )}
                    <span>
                      {cardSplitLoading
                        ? 'Searching Connecting Routes...'
                        : cardSplitResults !== null
                        ? cardSplitExpanded
                          ? 'Hide Alternative Routes'
                          : `Show Alternative Routes (${cardSplitResults.length})`
                        : 'Find Alternative Split Routes'}
                    </span>
                    {!cardSplitLoading && cardSplitResults !== null && (
                      cardSplitExpanded ? <ChevronUp size={14} /> : <ChevronDown size={14} />
                    )}
                  </Button>

                  {/* Inline Split Error */}
                  {cardSplitError && (
                    <div className="p-3 rounded-xl bg-rose-500/10 border border-rose-500/20 space-y-2 text-center">
                      <p className="text-xs font-bold text-rose-500">
                        {cardSplitError}
                      </p>
                      <button
                        type="button"
                        onClick={() => {
                          setCardSplitResults(null);
                          handleCardSplitSearch();
                        }}
                        className="px-3 py-1 bg-rose-500 text-white text-xs font-bold rounded-lg hover:bg-rose-600 transition-colors cursor-pointer"
                      >
                        Retry Search
                      </button>
                    </div>
                  )}

                  {/* Inline Loading for Split */}
                  {cardSplitLoading && (
                    <div className="py-2 animate-in fade-in duration-200">
                      <SplitJourneyLoader
                        originStation={fromStn}
                        destStation={toStn}
                        showHeader={false}
                        compact={true}
                      />
                    </div>
                  )}

                  {/* Inline Split Routes Results */}
                  {cardSplitExpanded && cardSplitResults !== null && !cardSplitLoading && (
                    <div className="space-y-3 pt-2 border-t border-blue-500/20 animate-in fade-in duration-200">
                      <div className="flex items-center justify-between px-0.5">
                        <span className="text-[11px] font-bold text-slate-700 dark:text-slate-300">
                          Connecting Alternatives ({cardSplitResults.length}):
                        </span>
                      </div>
                      {cardSplitResults.length === 0 ? (
                        <div className="bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl p-4 text-center">
                          <p className="text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">
                            No Split Routes Found
                          </p>
                          <p className="text-[11px] text-slate-500 leading-relaxed">
                            Our AI evaluated all major junctions, but no confirmed split routes were available for this date.
                          </p>
                        </div>
                      ) : (
                        <>
                          {cardSplitResults.length === 1 && (
                            <div
                              id={`single-alt-split-notice-${trainNo}`}
                              className="p-3 rounded-xl bg-blue-500/10 border border-blue-500/25 flex items-start gap-2.5 text-xs text-blue-900 dark:text-blue-200"
                            >
                              <Info className="w-4 h-4 text-primary shrink-0 mt-0.5" />
                              <div>
                                <span className="font-bold block text-slate-900 dark:text-white">
                                  Single Connecting Option Available
                                </span>
                                <span className="text-[11px] text-slate-600 dark:text-slate-300 leading-relaxed">
                                  Only 1 connecting route meets safe transfer layover (60m-180m) and running day requirements for this corridor on this date.
                                </span>
                              </div>
                            </div>
                          )}

                          {(showAllCardSplits ? cardSplitResults : cardSplitResults.slice(0, 2)).map((split: any, idx: number) => (
                            <InlineSplitRouteCard
                              key={idx}
                              split={split}
                              date={train.travelDate || date}
                              index={idx}
                              handleCheckAvailability={handleCheckAvailability}
                              availabilityMap={availabilityMap}
                              loadingTrain={loadingTrain}
                              selectedQuota={selectedQuota}
                              defaultClass={currentClass}
                            />
                          ))}

                          {cardSplitResults.length > 2 && (
                            <button
                              type="button"
                              id={`btn-view-more-alt-splits-${trainNo}`}
                              onClick={() => setShowAllCardSplits(p => !p)}
                              className="w-full py-2.5 px-4 text-xs font-bold text-primary border border-primary/25 rounded-xl bg-card hover:bg-primary/5 transition-all flex items-center justify-center gap-1.5 cursor-pointer shadow-xs min-h-[38px]"
                            >
                              {showAllCardSplits ? (
                                <>
                                  <ChevronUp className="w-3.5 h-3.5" />
                                  <span>Show Top 2 Alternative Routes</span>
                                </>
                              ) : (
                                <>
                                  <ChevronDown className="w-3.5 h-3.5" />
                                  <span>View More Alternative Routes (+{cardSplitResults.length - 2} more {cardSplitResults.length - 2 === 1 ? 'route' : 'routes'})</span>
                                </>
                              )}
                            </button>
                          )}

                          {cardSplitExhausted ? (
                            <div className="w-full py-2.5 px-4 text-xs font-bold text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-800 rounded-xl bg-slate-50 dark:bg-slate-900/50 text-center">
                              No More Alternative Junctions Available
                            </div>
                          ) : (
                            <button
                              type="button"
                              id={`btn-generate-more-alt-splits-${trainNo}`}
                              onClick={handleGenerateMoreCardSplits}
                              disabled={cardSplitLoading}
                              className="w-full py-2.5 px-4 text-xs font-bold text-primary border border-primary/25 rounded-xl bg-card hover:bg-primary/5 transition-all flex items-center justify-center gap-1.5 cursor-pointer shadow-xs disabled:opacity-50 min-h-[38px]"
                            >
                              <RefreshCw className="w-3.5 h-3.5 text-primary" />
                              <span>Generate New Alternative Routes</span>
                            </button>
                          )}
                        </>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}
        </div>
      </Card>
      {isSponsored && (
        <div className="bg-card/75 backdrop-blur-md p-5 rounded-3xl border border-yellow-500/25 shadow-elevated shadow-yellow-500/5 flex flex-col md:flex-row items-center justify-between gap-4 animate-in fade-in slide-in-from-bottom-2 duration-500 mt-4">
          <div>
            <p className="text-[10px] font-black tracking-widest text-yellow-500 uppercase mb-1">Sponsored</p>
            <p className="text-sm text-secondary font-semibold">🚀 Faster booking available on partner apps. Zero convenience fee!</p>
          </div>
          <button className="bg-yellow-500/10 hover:bg-yellow-500/20 text-yellow-500 border border-yellow-500/30 px-6 py-2.5 rounded-xl text-sm font-bold transition-all whitespace-nowrap cursor-pointer active:scale-95">
            Try Now
          </button>
        </div>
      )}

      {showScheduleModal && (
        <TrainScheduleModal
          trainNo={trainNo}
          trainName={info.name}
          date={train.travelDate || date}
          fromStn={fromStn}
          toStn={toStn}
          initialTab={scheduleModalTab}
          onClose={() => setShowScheduleModal(false)}
        />
      )}

      <LimitReachedModal
        isOpen={showPaywallModal}
        onClose={() => setShowPaywallModal(false)}
        source="waitlist_funnel"
        actionType={paywallAction}
      />
      <LoginModal
        isOpen={showLoginModal}
        onClose={() => setShowLoginModal(false)}
        contextMessage={loginContextMessage}
      />
    </React.Fragment>
  );
};
